import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Max Pooling 1D
maxpool1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void maxpool1d_kernel(const float* input, float* output, int batch_size, int num_features, int sequence_length, int kernel_size, int stride, int padding, int dilation) {
    int output_sequence_length = (sequence_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * num_features * output_sequence_length) {
        int b = idx / (num_features * output_sequence_length);
        int f = (idx % (num_features * output_sequence_length)) / output_sequence_length;
        int s = idx % output_sequence_length;
        int start_idx = s * stride - padding;
        float max_val = -INFINITY;
        for (int k = 0; k < kernel_size; ++k) {
            int input_idx = start_idx + k * dilation;
            if (input_idx >= 0 && input_idx < sequence_length) {
                float val = input[b * num_features * sequence_length + f * sequence_length + input_idx];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
        output[idx] = max_val;
    }
}

torch::Tensor maxpool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    int sequence_length = input.size(2);
    int output_sequence_length = (sequence_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, num_features, output_sequence_length}, input.options());

    const int block_size = 256;
    int num_elements = batch_size * num_features * output_sequence_length;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    maxpool1d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, num_features, sequence_length, kernel_size, stride, padding, dilation);

    return output;
}
"""

maxpool1d_cpp_source = (
    "torch::Tensor maxpool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation);"
)

# Compile the inline CUDA code for Max Pooling 1D
maxpool1d = load_inline(
    name="maxpool1d",
    cpp_sources=maxpool1d_cpp_source,
    cuda_sources=maxpool1d_source,
    functions=["maxpool1d_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices
        self.maxpool1d = maxpool1d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.maxpool1d.maxpool1d_cuda(x, self.kernel_size, self.stride, self.padding, self.dilation)
